- (void)viewDidLoad{[super viewDidLoad];self.title=@"网易云登录";self.view.backgroundColor=UIColor.systemBackgroundColor;_qr=[UIImageView new];_qr.contentMode=UIViewContentModeScaleAspectFit;_note=[UILabel new];_note.numberOfLines=0;_note.textAlignment=NSTextAlignmentCenter;_note.text=@"正在获取二维码…\n请用网易云 App 扫码并确认。登录态仅保存在本机钥匙串。";
