- (void)check{if(_checking)return;if([_expiry timeIntervalSinceNow]<=0){[_timer invalidate];_note.text=@"二维码过期，请返回重试";return;}_checking=YES;__weak typeof(self) weak=self;[[TMMusicAPI shared]request:@"/api/login/qrcode/client/login" payload:@{@"key":_key,@"type":@3} eapi:YES done:^(NSDictionary *j,NSString *error){TMLoginPanel *s=weak;if(!s)return;s.checking=NO;NSInteger code=[j[@"code"]integerValue];if(code==803){[s.timer invalidate];s.note.text=TMMusicAPI.shared.hasLogin?@"已登录，返回音乐页即可使用":@"已确认，但未保存登录态，请重试";}else if(code==800){[s.timer invalidate];s.note.text=@"二维码已过期";}else if(code==802)s.note.text=@"已扫码，请在网易云确认";else if(error)s.note.text=error;}];}
- (void)viewDidDisappear:(BOOL)animated{[super viewDidDisappear:animated];[_timer invalidate];_timer=nil;}
