static UIImage *IdleCover(void){UIGraphicsImageRendererFormat *f=[UIGraphicsImageRendererFormat defaultFormat];f.scale=1;return [[[UIGraphicsImageRenderer alloc]initWithSize:CGSizeMake(320,320) format:f]imageWithActions:^(UIGraphicsImageRendererContext *r){CGContextRef c=r.CGContext;CGColorSpaceRef cs=CGColorSpaceCreateDeviceRGB();CGFloat colors[]={.22,.15,.12,1,.065,.055,.055,1};CGGradientRef g=CGGradientCreateWithColorComponents(cs,colors,NULL,2);CGContextDrawLinearGradient(c,g,CGPointZero,CGPointMake(320,320),0);CGGradientRelease(g);CGColorSpaceRelease(cs);for(int i=0;i<8;i++){[[UIColor colorWithWhite:.85 alpha:.035]setStroke];UIBezierPath *p=[UIBezierPath bezierPathWithOvalInRect:CGRectMake(34+i*8,34+i*8,252-i*16,252-i*16)];p.lineWidth=1;[p stroke];}UIImage *note=[UIImage systemImageNamed:@"music.note" withConfiguration:[UIImageSymbolConfiguration configurationWithPointSize:64 weight:UIImageSymbolWeightLight]];[[note imageWithTintColor:[UIColor colorWithRed:.96 green:.7 blue:.49 alpha:1] renderingMode:UIImageRenderingModeAlwaysOriginal]drawInRect:CGRectMake(130,120,60,76)];[@"T U R B O   I O" drawAtPoint:CGPointMake(96,276) withAttributes:@{NSFontAttributeName:[UIFont systemFontOfSize:13 weight:UIFontWeightMedium],NSForegroundColorAttributeName:[UIColor colorWithWhite:.65 alpha:1]}];}];}
