- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];__weak typeof(self) weak=self;_refreshTimer=[NSTimer scheduledTimerWithTimeInterval:.4 repeats:YES block:^(NSTimer *t){[weak refresh];}];}
- (void)viewDidDisappear:(BOOL)animated{[super viewDidDisappear:animated];[_refreshTimer invalidate];_refreshTimer=nil;}
- (void)refresh{TMPlayer *p=TMPlayer.shared;_songLabel.text=p.song[@"name"]?:@"随音乐，看见歌词";_artistLabel.text=p.song[@"artist"]?:@"选择一首歌，开始你的音乐旅程";if(_lastCover!=p.cover){_lastCover=p.cover;_art.image=p.cover?:TIOArtwork(@"music")?:IdleCover();}_stateLabel.text=p.status;BOOL steady=[p.status isEqual:@"播放中"]||[p.status isEqual:@"已暂停"]||!p.song;_stateLabel.hidden=steady;_bridgeLabel.text=p.glasses?p.bridgeStatus:@"将封面与歌词同步到眼镜，需要音乐版固件。";_glassesSwitch.on=p.glasses;_displayMode.enabled=p.glasses;_displayMode.alpha=p.glasses?1:.5;_timeLabel.text=[NSString stringWithFormat:@"%02ld:%02ld  /  %02ld:%02ld",(long)p.position/60,(long)p.position%60,(long)p.duration/60,(long)p.duration%60];if(!_progress.tracking){_progress.maximumValue=MAX(1,p.duration);_progress.value=p.position;}UIButtonConfiguration *c=_playButton.configuration;c.title=@"";c.image=[UIImage systemImageNamed:p.playing?@"pause.fill":@"play.fill"];_playButton.configuration=c;_playButton.accessibilityLabel=p.playing?@"暂停":@"播放";NSString *line=p.song?@"让旋律慢慢流淌":@"你的下一段旋律，在这里";NSInteger current=-1;for(NSUInteger i=0;i<p.lyrics.count;i++){if([p.lyrics[i][@"ms"]doubleValue]>p.position*1000)break;current=i;}if(current>=0){NSMutableAttributedString *text=[NSMutableAttributedString new];for(NSInteger i=MAX(0,current-1);i<MIN((NSInteger)p.lyrics.count,current+2);i++){if(text.length)[text appendAttributedString:[[NSAttributedString alloc]initWithString:@"\n"]];NSDictionary *attrs=@{NSForegroundColorAttributeName:i==current?TIOInk():UIColor.secondaryLabelColor,NSFontAttributeName:[UIFont systemFontOfSize:i==current?17:14 weight:i==current?UIFontWeightMedium:UIFontWeightRegular]};[text appendAttributedString:[[NSAttributedString alloc]initWithString:p.lyrics[i][@"text"]?:@"" attributes:attrs]];}_lyricLabel.attributedText=text;}else if(![_lyricLabel.text isEqual:line]){_lyricLabel.text=line;}[self.view setNeedsLayout];}
- (void)pageModeChanged{_playerStack.hidden=_pageMode.selectedSegmentIndex==1;_discoveryStack.hidden=!_playerStack.hidden;[self.tableView reloadData];[self.view setNeedsLayout];}
- (void)toggleDisplaySettings{_showDisplaySettings=!_showDisplaySettings;_displayMode.hidden=!_showDisplaySettings;[self.view setNeedsLayout];}
- (void)more{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"音乐" message:nil preferredStyle:UIAlertControllerStyleActionSheet];__weak typeof(self) weak=self;[a addAction:[UIAlertAction actionWithTitle:@"打开网易云歌单" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[weak playlist];}]];[a addAction:[UIAlertAction actionWithTitle:@"显示到眼镜" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[weak showGlasses];}]];[a addAction:[UIAlertAction actionWithTitle:@"关闭眼镜画面" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[weak hideGlasses];}]];[a addAction:[UIAlertAction actionWithTitle:@"播放本机校验曲" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[weak demo];}]];[a addAction:[UIAlertAction actionWithTitle:@"连接与播放状态" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){TMMusicPanel *s=weak;if(!s)return;UIAlertController *d=[UIAlertController alertControllerWithTitle:@"播放诊断" message:[NSString stringWithFormat:@"%@\n\n%@",TMPlayer.shared.status,TMPlayer.shared.bridgeStatus] preferredStyle:UIAlertControllerStyleAlert];[d addAction:[UIAlertAction actionWithTitle:@"完成" style:UIAlertActionStyleCancel handler:nil]];[s presentViewController:d animated:YES completion:nil];}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItems.firstObject;[self presentViewController:a animated:YES completion:nil];}
- (void)toggle{[TMPlayer.shared play:!TMPlayer.shared.playing];}- (void)previous{[TMPlayer.shared step:-1];}- (void)next{[TMPlayer.shared step:1];}- (void)seek{[TMPlayer.shared seek:_progress.value];}- (void)demo{[TMPlayer.shared demo];}- (void)modeChanged{TMPlayer.shared.mode=_displayMode.selectedSegmentIndex;}- (void)glassesChanged{TMPlayer.shared.glasses=_glassesSwitch.on;}- (void)showGlasses{[TMPlayer.shared showOnGlasses];}- (void)hideGlasses{[TMPlayer.shared hideGlasses];}
- (void)login{if(!TMMusicAPI.shared.hasLogin){[self.navigationController pushViewController:[TMLoginPanel new] animated:YES];return;}UIAlertController *a=[UIAlertController alertControllerWithTitle:@"网易云账号" message:@"已登录，凭据仅保存在本机钥匙串。不使用已有独立网易云 App 的登录状态。" preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"关闭" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"退出账号" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){[TMPlayer.shared play:NO];[TMMusicAPI.shared logout];[self refresh];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)playlist{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"打开网易云歌单" message:@"输入歌单 ID（分享链接中的 id）。当前账号无权访问的内容不会绕过限制。" preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField *f){f.placeholder=@"歌单 ID";f.keyboardType=UIKeyboardTypeNumberPad;}];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"打开" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){long long n=a.textFields.firstObject.text.longLongValue;if(n<=0)return;[self load:@"/api/v6/playlist/detail" payload:@{@"id":@(n),@"n":@100,@"s":@8} eapi:YES];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)searchBarSearchButtonClicked:(UISearchBar *)searchBar{[searchBar resignFirstResponder];NSString *s=[searchBar.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];if(s.length)[self load:@"/api/cloudsearch/pc" payload:@{@"s":s,@"type":@1,@"limit":@30,@"offset":@0,@"total":@YES} eapi:NO];}
- (void)load:(NSString *)path payload:(NSDictionary *)payload eapi:(BOOL)eapi{NSUInteger ticket=++_searchTicket;self.navigationItem.prompt=@"正在加载…";__weak typeof(self) weak=self;[TMMusicAPI.shared request:path payload:payload eapi:eapi done:^(NSDictionary *j,NSString *err){TMMusicPanel *s=weak;if(!s||s.searchTicket!=ticket)return;id parent=j[eapi?@"playlist":@"result"];id list=[parent isKindOfClass:NSDictionary.class]?parent[eapi?@"tracks":@"songs"]:nil;NSMutableArray *valid=[NSMutableArray new];if([list isKindOfClass:NSArray.class])for(id row in list)if([row isKindOfClass:NSDictionary.class])[valid addObject:row];s.results=valid;s.pageMode.selectedSegmentIndex=1;[s pageModeChanged];s.navigationItem.prompt=err?:[NSString stringWithFormat:@"%lu 首 · 向下选择歌曲",(unsigned long)s.results.count];[s.tableView reloadData];if(s.results.count)[s.tableView scrollToRowAtIndexPath:[NSIndexPath indexPathForRow:0 inSection:0]atScrollPosition:UITableViewScrollPositionTop animated:YES];}];}
- (NSInteger)tableView:(UITableView *)tableView numberOfRowsInSection:(NSInteger)section{return _pageMode.selectedSegmentIndex==1?_results.count:0;}
- (UITableViewCell *)tableView:(UITableView *)tableView cellForRowAtIndexPath:(NSIndexPath *)ip{UITableViewCell *c=[tableView dequeueReusableCellWithIdentifier:@"song"]?:[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:@"song"];id s=_results[ip.row];c.textLabel.text=[s[@"name"]isKindOfClass:NSString.class]?s[@"name"]:@"歌曲";NSArray *ar=[s[@"ar"]isKindOfClass:NSArray.class]?s[@"ar"]:@[];NSMutableArray *names=[NSMutableArray new];for(id a in ar)if([a[@"name"]isKindOfClass:NSString.class])[names addObject:a[@"name"]];c.detailTextLabel.text=[names componentsJoinedByString:@" / "];c.imageView.image=[UIImage systemImageNamed:@"music.note"];c.imageView.tintColor=TIOAccent();c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;c.backgroundColor=UIColor.secondarySystemGroupedBackgroundColor;return c;}
- (CGFloat)tableView:(UITableView *)tableView heightForRowAtIndexPath:(NSIndexPath *)ip{return 64;}
- (void)tableView:(UITableView *)tableView didSelectRowAtIndexPath:(NSIndexPath *)ip{[tableView deselectRowAtIndexPath:ip animated:YES];[TMPlayer.shared playSong:_results[ip.row] queue:_results];self.pageMode.selectedSegmentIndex=0;[self pageModeChanged];[tableView setContentOffset:CGPointMake(0,-tableView.adjustedContentInset.top) animated:YES];}
